using var adapter = new LabScriptedAdapter();
using var c = new LabController(adapter);
string old = c.Submit("QueryState", 0);
c.Reconnect();
Console.WriteLine($"{c.Session} {c.Connected} {c.Authenticated} {c.DeviceReady}"); // 2 True False False
try { c.Submit("QueryState", 0); }
catch (InvalidOperationException) { Console.WriteLine("blocked until verified and ready"); }
c.Authenticated = true; c.DeviceReady = true; // 測試注入，不是生產認證程式碼
string current = c.Submit("QueryState", 0);
Console.WriteLine(adapter.Sent.Count); // 2，受阻操作未送出

using var adapter = new LabScriptedAdapter();
using var c = new LabController(adapter);
c.Reconnect(); c.Authenticated = c.DeviceReady = true;
string id = c.Submit("QueryState", 0);
adapter.Emit(new LabCompletion(id, 1, "Completed"));
Console.WriteLine($"{c.Results[id]} {c.Applied} {c.Ignored}"); // Pending 0 1
adapter.Emit(new LabCompletion(id, 2, "Completed"));
Console.WriteLine($"{c.Results[id]} {c.Applied} {c.Ignored}"); // Completed 1 1
adapter.Emit(new LabCompletion(id, 2, "Completed"));
Console.WriteLine(c.Applied); // 1
